 <?php $__env->startSection('title',$type==='in'?'Stok Masuk':'Stok Keluar'); ?> <?php $__env->startSection('heading',$type==='in'?'Catat Stok Masuk':'Catat Stok Keluar'); ?> <?php $__env->startSection('crumb','Transaksi Stok'); ?>
<?php $__env->startSection('content'); ?><div class="row"><div class="col-lg-8"><form method="POST" action="<?php echo e($type==='in'?route('stock.in.store'):route('stock.out.store')); ?>"><?php echo csrf_field(); ?><div class="panel p-4"><p class="muted mb-4">Catat pergerakan stok dengan nomor transaksi otomatis.</p><div class="mb-3"><label class="form-label">Produk *</label><select class="form-select" name="product_id" required><option value="">Pilih produk</option><?php $__currentLoopData = $products; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $p): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($p->id); ?>" <?php if(old('product_id')==$p->id): echo 'selected'; endif; ?>><?php echo e($p->sku); ?> — <?php echo e($p->name); ?> (stok: <?php echo e($p->stock); ?> <?php echo e($p->unit); ?>)</option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="mb-3"><label class="form-label">Jumlah *</label><input class="form-control" type="number" name="quantity" min="1" value="<?php echo e(old('quantity',1)); ?>" required></div><div class="mb-4"><label class="form-label">Catatan</label><textarea class="form-control" rows="3" name="note" placeholder="Referensi atau keterangan transaksi..."><?php echo e(old('note')); ?></textarea></div><button class="btn btn-success"><i class="bi bi-check-lg"></i> Simpan Transaksi</button> <a href="<?php echo e(route('stock.history')); ?>" class="btn btn-light">Batal</a></div></form></div><div class="col-lg-4 mt-3 mt-lg-0"><div class="panel p-4"><i class="bi <?php echo e($type==='in'?'bi-box-arrow-in-down':'bi-box-arrow-up'); ?> fs-2 text-success"></i><h6 class="fw-bold mt-3"><?php echo e($type==='in'?'Stok Masuk':'Stok Keluar'); ?></h6><p class="muted small mb-0"><?php echo e($type==='in'?'Jumlah stok akan bertambah setelah transaksi berhasil.':'Jumlah stok akan berkurang. Sistem menolak transaksi jika stok tidak mencukupi.'); ?></p></div></div></div><?php $__env->stopSection(); ?>

